from pathlib import Path
import re,json
from html import escape

out=Path(__file__).parent
source=out.parent/'visualization-design-2026-10-06-v11/index.html'
d=json.loads(re.search(r'<script id="data" type="application/json">(.*?)</script>',source.read_text(encoding='utf8'),re.S)[1])
tid='understat:83'
ms=[m for m in d['completed'] if m['season']=='2025/26' and tid in (m['home'],m['away'])]
ms.sort(key=lambda m:(m['date'],m['id']))
gf=lambda m:m['hg'] if m['home']==tid else m['ag']
ga=lambda m:m['ag'] if m['home']==tid else m['hg']
w=sum(gf(m)>ga(m) for m in ms);draw=sum(gf(m)==ga(m) for m in ms);loss=len(ms)-w-draw
goals=int(sum(gf(m) for m in ms));against=int(sum(ga(m) for m in ms))
xg=sum(m['hx'] if m['home']==tid else m['ax'] for m in ms)
logo=escape(d['teams'][tid]['logo'],quote=True)
badge=f'<img class="logo" src="{logo}" alt="Arsenal 로고" onerror="this.hidden=true" loading="lazy">'
form=''.join(f'<span class="form {"win" if gf(m)>ga(m) else "draw" if gf(m)==ga(m) else "loss"}">{"승" if gf(m)>ga(m) else "무" if gf(m)==ga(m) else "패"}</span>' for m in ms[-5:])
summary=f'{w}승 {draw}무 {loss}패'
stats=f'<div class="stat"><small>승점</small><b>{w*3+draw}</b></div><div class="stat"><small>득점</small><b>{goals}</b></div><div class="stat"><small>실점</small><b>{against}</b></div>'
chart='<svg viewBox="0 0 300 100" role="img" aria-label="최근 8경기 기대 득점">'+''.join(f'<rect x="{i*36+12}" y="{90-min(80,(m["hx"] if m["home"]==tid else m["ax"])*20):.1f}" width="20" height="{min(80,(m["hx"] if m["home"]==tid else m["ax"])*20):.1f}" rx="5" fill="currentColor"/>' for i,m in enumerate(ms[-8:]))+'</svg>'
page='''<!doctype html><html lang="ko"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Matchdesk 디자인 후보</title><style>
*{box-sizing:border-box}body{margin:0;background:#f3f4f7;color:#182b40;font:16px/1.6 system-ui,"맑은 고딕",sans-serif}.wrap{max-width:1440px;margin:auto;padding:40px 24px}h1{font-size:clamp(25px,3vw,38px);letter-spacing:-1px;margin:0 0 8px}.intro{color:#617086;margin:0 0 26px}.gallery{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:24px}.option h2{font-size:20px;margin:0}.option>p{font-size:14px;color:#617086;margin:6px 0 18px}.preview{min-height:560px;overflow:hidden;border-radius:24px;box-shadow:0 10px 35px #182b4012}.preview header{display:flex;justify-content:space-between;gap:12px;font-size:12px;font-weight:700;padding:20px 22px}.preview main{padding:0 22px 26px}.logo{width:60px;height:60px;object-fit:contain}.club{display:flex;align-items:center;gap:14px}.club h3{font-size:28px;line-height:1.2;margin:0}.club p{margin:4px 0 0;font-size:13px}.season{font-size:12px;margin:16px 0;color:inherit;opacity:.8}.statrow{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:10px}.stat{min-width:0}.stat small{display:block;font-size:12px}.stat b{display:block;font-size:30px;line-height:1.4;font-variant-numeric:tabular-nums}.card{padding:18px;margin:20px 0 0;border-radius:18px}.card h4{margin:0 0 10px;font-size:14px}.form{display:inline-grid;place-items:center;width:34px;height:34px;border-radius:10px;font-size:13px;font-weight:700;margin-right:5px}.win{background:#dceee3;color:#245e3f}.draw{background:#e9e9e9;color:#555}.loss{background:#f4dddf;color:#943038}.chart{margin-top:22px}.chart p{font-size:13px;margin:0}.chart svg{width:100%;height:100px}.tabs{display:flex;gap:10px;margin:22px 0;font-size:13px}.tabs span{padding:7px 13px;border-radius:30px}.foot{font-size:13px;color:#617086;margin-top:26px}.soft{background:#faf8f5}.soft header{color:#6d747d}.soft .club{margin-top:14px}.soft .statrow{margin-top:22px}.soft .stat{background:white;padding:14px;border-radius:18px;box-shadow:0 3px 15px #29384d06}.soft .card{background:#f1e7e5}.soft .chart{color:#b5313b}.soft .tabs span:first-child{background:#b5313b;color:white}.soft .tabs span{background:white}.stadium{background:#191e27;color:#f5f5f6}.stadium header{background:#131820;color:#c9d0db}.stadium .hero{margin:0 -22px;padding:26px 22px;background:radial-gradient(ellipse at 100% 0,#e9374c66,transparent 70%),#68232f}.stadium .logo{width:78px;height:78px}.stadium .club h3{font-size:34px}.stadium .season{margin-bottom:0;color:#ecd4d7}.stadium .tabs span:first-child{background:#f7d56e;color:#24252a}.stadium .statrow{padding:14px 0}.stadium .stat b{color:#f8d671}.stadium .card{background:#272f3c}.stadium .chart{color:#f1717e}.editorial{background:white;border-radius:8px}.editorial header{border-bottom:2px solid #152c32;font-size:14px;letter-spacing:1px}.editorial .eyebrow{font-size:12px;color:#a4313b;letter-spacing:2px;margin:24px 0 8px}.editorial .club h3{font-family:Georgia,serif;font-size:40px}.editorial .club{justify-content:space-between}.editorial .logo{width:55px;height:55px}.editorial .statrow{margin-top:26px;padding:18px 0;border-top:1px solid #dce3e4;border-bottom:1px solid #dce3e4}.editorial .stat b{font-family:Georgia,serif}.editorial .card{padding:0;border-radius:0;margin-top:26px}.editorial .chart{color:#315a51}.editorial .tabs{border-bottom:1px solid #dce3e4;padding-bottom:8px}.editorial .tabs span{padding:0 7px 0 0;border-radius:0}.editorial .tabs span:first-child{color:#a4313b;font-weight:700}.tag{display:inline-block;font-size:11px;background:#e4edff;color:#214a8d;padding:3px 9px;border-radius:20px;margin-left:6px}a{color:#225c98}button:focus-visible,a:focus-visible{outline:2px solid #225c98;outline-offset:4px}@media(max-width:1050px){.gallery{grid-template-columns:1fr;max-width:560px;margin:auto}.wrap{padding:28px 18px}.preview{min-height:0}}
</style><div class="wrap"><h1>같은 데이터, 세 가지 분위기</h1><p class="intro">Arsenal · 2025/26 수집 자료로 만든 디자인 비교 시안입니다. 기존 사이트에는 아직 적용하지 않았습니다.</p><div class="gallery">'''
page+=f'''<section class="option"><h2>① 부드러운 분석 앱 <span class="tag">추천</span></h2><p>밝고 편안하게. 팀 색은 필요한 곳에만.</p><div class="preview soft"><header><span>matchdesk</span><span>내 팀의 기록</span></header><main><div class="club">{badge}<div><h3>Arsenal</h3><p>{summary}</p></div></div><div class="season">2025/26 · {len(ms)}경기</div><div class="tabs"><span>한눈에</span><span>경기 기록</span><span>상세 지표</span></div><div class="statrow">{stats}</div><div class="card"><h4>최근 5경기 흐름</h4>{form}</div><div class="chart"><p>최근 8경기 기대 득점</p>{chart}</div></main></div></section>'''
page+=f'''<section class="option"><h2>② 경기장 분위기의 팬 앱</h2><p>큰 로고와 팀 색. 경기 보는 느낌을 강조.</p><div class="preview stadium"><header><span>MATCHDESK / CLUB</span><span>PREMIER LEAGUE</span></header><main><div class="hero"><div class="club">{badge}<div><h3>Arsenal</h3><p>{summary}</p></div></div><div class="season">2025/26 · {len(ms)}경기</div></div><div class="tabs"><span>팀 홈</span><span>경기</span><span>기록</span></div><div class="statrow">{stats}</div><div class="card"><h4>최근 5경기</h4>{form}</div><div class="chart"><p>최근 8경기 기대 득점</p>{chart}</div></main></div></section>'''
page+=f'''<section class="option"><h2>③ 축구 매거진</h2><p>큰 제목과 차트. 카드 반복을 줄이고 여백으로 구분.</p><div class="preview editorial"><header><span>THE MATCHDESK</span><span>팀 기록</span></header><main><p class="eyebrow">CLUB / 2025–26</p><div class="club"><div><h3>Arsenal</h3><p>{summary} · {len(ms)}경기</p></div>{badge}</div><div class="tabs"><span>시즌 이야기</span><span>경기 기록</span><span>상세 통계</span></div><div class="statrow">{stats}</div><div class="chart"><p>최근 8경기 기대 득점</p>{chart}</div><div class="card"><h4>최근 5경기 결과</h4>{form}</div></main></div></section>'''
page+='</div><p class="foot">시안의 메뉴는 구성 예시입니다. 숫자와 최근 결과는 기존 수집 자료에서 계산했습니다. 후보 선택 후 실제 검색·지표 말풍선에 연결합니다.</p></div></html>'
assert not (out/'index.html').exists()
(out/'index.html').write_text(page,encoding='utf8')
print(f'Created 3 design candidates using {len(ms)} actual matches. W/D/L={w}/{draw}/{loss}. Goals={goals}/{against}.')
